changeSet.sql:
UPDATE metaforge_chat SET user_id = (SELECT MAX(r.user_id) FROM metaforge_chat_user_relation r WHERE r.chat_id = metaforge_chat.id);
UPDATE metaforge_message SET user_id = (SELECT MAX(r.user_id) FROM metaforge_message_user_relation r WHERE r.message_id = metaforge_message.id);
UPDATE metaforge_message SET chat_id = (SELECT MAX(r.chat_id) FROM metaforge_message_chat_relation r WHERE r.message_id = metaforge_message.id);
UPDATE metaforge_dashboard SET user_id = (SELECT MAX(r.user_id) FROM metaforge_dashboard_user_relation r WHERE r.dashboard_id = metaforge_dashboard.id);
UPDATE metaforge_report SET user_id = (SELECT MAX(r.user_id) FROM metaforge_report_user_relation r WHERE r.report_id = metaforge_report.id);
UPDATE metaforge_report SET source_id = (SELECT MAX(r.source_id) FROM metaforge_report_source_relation r WHERE r.report_id = metaforge_report.id);
UPDATE metaforge_report SET dataset_id = (SELECT MAX(r.dataset_id) FROM metaforge_report_dataset_relation r WHERE r.report_id = metaforge_report.id);
UPDATE metaforge_dataset SET user_id = (SELECT MAX(r.user_id) FROM metaforge_dataset_user_relation r WHERE r.dataset_id = metaforge_dataset.id);
UPDATE metaforge_dataset SET source_id = (SELECT MAX(r.source_id) FROM metaforge_dataset_source_relation r WHERE r.dataset_id = metaforge_dataset.id);
UPDATE metaforge_dataset_column SET dataset_id = (SELECT MAX(r.dataset_id) FROM metaforge_dataset_column_relation r WHERE r.column_id = metaforge_dataset_column.id)
    WHERE EXISTS (SELECT 1 FROM metaforge_dataset_column_relation r WHERE r.column_id = metaforge_dataset_column.id);
UPDATE metaforge_dataset_history SET dataset_id = (SELECT MAX(r.dataset_id) FROM metaforge_dataset_history_relation r WHERE r.dataset_history_id = metaforge_dataset_history.id);
UPDATE metaforge_scheduled_history SET source_id = (SELECT MAX(r.source_id) FROM metaforge_scheduled_history_source_relation r WHERE r.scheduled_history_id = metaforge_scheduled_history.id);

ALTER TABLE metaforge_source RENAME COLUMN `_type` TO source_type;
ALTER TABLE metaforge_source RENAME COLUMN `_catalog` TO catalog_name;
ALTER TABLE metaforge_source RENAME COLUMN `_database` TO database_name;
ALTER TABLE metaforge_source RENAME COLUMN `_ssl` TO use_ssl;
ALTER TABLE metaforge_source RENAME COLUMN `public` TO is_public;
ALTER TABLE metaforge_source RENAME COLUMN `password` TO connection_password;
ALTER TABLE metaforge_user RENAME COLUMN `password` TO password_hash;
ALTER TABLE metaforge_dataset_column RENAME COLUMN `comment` TO column_comment;
ALTER TABLE metaforge_workflow RENAME COLUMN j_from_id TO from_source_id;
ALTER TABLE metaforge_workflow RENAME COLUMN j_to_id TO to_source_id;
ALTER TABLE metaforge_workflow RENAME COLUMN j_user_id TO user_id;
ALTER TABLE metaforge_source_query RENAME COLUMN plugin_id TO source_id;

ALTER TABLE metaforge_source ALTER COLUMN `_type` RENAME TO source_type;
ALTER TABLE metaforge_source ALTER COLUMN `_catalog` RENAME TO catalog_name;
ALTER TABLE metaforge_source ALTER COLUMN `_database` RENAME TO database_name;
ALTER TABLE metaforge_source ALTER COLUMN `_ssl` RENAME TO use_ssl;
ALTER TABLE metaforge_source ALTER COLUMN `public` RENAME TO is_public;
ALTER TABLE metaforge_source ALTER COLUMN `password` RENAME TO connection_password;
ALTER TABLE metaforge_user ALTER COLUMN `password` RENAME TO password_hash;
ALTER TABLE metaforge_dataset_column ALTER COLUMN `comment` RENAME TO column_comment;
ALTER TABLE metaforge_workflow ALTER COLUMN j_from_id RENAME TO from_source_id;
ALTER TABLE metaforge_workflow ALTER COLUMN j_to_id RENAME TO to_source_id;
ALTER TABLE metaforge_workflow ALTER COLUMN j_user_id RENAME TO user_id;
ALTER TABLE metaforge_source_query ALTER COLUMN plugin_id RENAME TO source_id;

ALTER TABLE metaforge_dataset_column MODIFY is_primary_key TINYINT(1) DEFAULT 0;
ALTER TABLE metaforge_source_query ADD COLUMN create_time_value DATETIME NULL;
UPDATE metaforge_source_query SET create_time_value = CAST(LEFT(create_time, 19) AS DATETIME)
    WHERE create_time REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}';
ALTER TABLE metaforge_source_query DROP COLUMN create_time;
ALTER TABLE metaforge_source_query RENAME COLUMN create_time_value TO create_time;

ALTER TABLE metaforge_dataset_column ALTER COLUMN is_primary_key BOOLEAN;
ALTER TABLE metaforge_dataset_column ALTER COLUMN is_primary_key SET DEFAULT FALSE;
ALTER TABLE metaforge_source_query ADD COLUMN create_time_value TIMESTAMP NULL;
UPDATE metaforge_source_query SET create_time_value = CAST(LEFT(CAST(create_time AS VARCHAR(64)), 19) AS TIMESTAMP)
    WHERE REGEXP_LIKE(CAST(create_time AS VARCHAR(64)), '^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}');
ALTER TABLE metaforge_source_query DROP COLUMN create_time;
ALTER TABLE metaforge_source_query ALTER COLUMN create_time_value RENAME TO create_time;
